/// The request signatures of interface `name`.
pub fn requests(name: &str) -> &'static [&'static str] {
    match name {
        wl_display::NAME => wl_display::REQUESTS,
        wl_registry::NAME => wl_registry::REQUESTS,
        wl_callback::NAME => wl_callback::REQUESTS,
        wl_compositor::NAME => wl_compositor::REQUESTS,
        wl_shm_pool::NAME => wl_shm_pool::REQUESTS,
        wl_shm::NAME => wl_shm::REQUESTS,
        wl_buffer::NAME => wl_buffer::REQUESTS,
        wl_data_offer::NAME => wl_data_offer::REQUESTS,
        wl_data_source::NAME => wl_data_source::REQUESTS,
        wl_data_device::NAME => wl_data_device::REQUESTS,
        wl_data_device_manager::NAME => wl_data_device_manager::REQUESTS,
        wl_shell::NAME => wl_shell::REQUESTS,
        wl_shell_surface::NAME => wl_shell_surface::REQUESTS,
        wl_surface::NAME => wl_surface::REQUESTS,
        wl_seat::NAME => wl_seat::REQUESTS,
        wl_pointer::NAME => wl_pointer::REQUESTS,
        wl_keyboard::NAME => wl_keyboard::REQUESTS,
        wl_touch::NAME => wl_touch::REQUESTS,
        wl_output::NAME => wl_output::REQUESTS,
        wl_region::NAME => wl_region::REQUESTS,
        wl_subcompositor::NAME => wl_subcompositor::REQUESTS,
        wl_subsurface::NAME => wl_subsurface::REQUESTS,
        xdg_wm_base::NAME => xdg_wm_base::REQUESTS,
        xdg_positioner::NAME => xdg_positioner::REQUESTS,
        xdg_surface::NAME => xdg_surface::REQUESTS,
        xdg_toplevel::NAME => xdg_toplevel::REQUESTS,
        xdg_popup::NAME => xdg_popup::REQUESTS,
        zxdg_decoration_manager_v1::NAME => zxdg_decoration_manager_v1::REQUESTS,
        zxdg_toplevel_decoration_v1::NAME => zxdg_toplevel_decoration_v1::REQUESTS,
        wp_viewporter::NAME => wp_viewporter::REQUESTS,
        wp_viewport::NAME => wp_viewport::REQUESTS,
        _ => &[],
    }
}
